(7413821, 1167986, 7889, '<td valign="top">Focus is off, a higher speed setting would help</td>', 'Focus is off, a higher speed setting would help', '2015-11-03 04:49:46.000000', NULL, 1),
(7413822, 1168050, 7889, '<td valign="top">Not a big fan of desaturated images, the subject would have been better if she was facing towards you, however you probably had no control over that. The result is not a very interesting photo.</td>', 'Not a big fan of desaturated images, the subject would have been better if she was facing towards you, however you probably had no control over that. The result is not a very interesting photo.', '2015-11-03 04:51:18.000000', NULL, 1),
