(7414770, 1169151, 65234, '<td valign="top">It''s hard to tell if the clouds dipped down to meet the water or the water swirled up to meet the clouds. And that''s sublime.</td>', 'It''s hard to tell if the clouds dipped down to meet the water or the water swirled up to meet the clouds. And that''s sublime.', '2015-11-07 10:27:13.000000', NULL, 1),
(7414771, 1169107, 65234, '<td valign="top">Wonderfully moody. That boat has been beached for quite awhile, it looks like. Water can be so very powerful, but here it looks sad, diminished, helpless.</td>', 'Wonderfully moody. That boat has been beached for quite awhile, it looks like. Water can be so very powerful, but here it looks sad, diminished, helpless.', '2015-11-07 10:28:53.000000', NULL, 1),
